<?php
namespace App\Http\Controllers;
use App\Exports\TrainingAnalyticsExport;use App\Http\Requests\CreateTrainingNeedFromGapRequest;use App\Models\{Empleado,TrainingNeed,TrainingRequirement};use App\Services\TrainingGapService;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Maatwebsite\Excel\Facades\Excel;
class TrainingGapController extends Controller{public function index(Request$r,TrainingGapService$s){$gaps=$s->forCompany($r->user()->company_id,$r->only('job','area'));$summary=$s->summary($r->user()->company_id,$r->only('job','area'));return view('training.gaps.index',compact('gaps','summary'));}public function createNeed(CreateTrainingNeedFromGapRequest$r){$c=$r->user()->company_id;$d=$r->validated();$employee=Empleado::where('company_id',$c)->findOrFail($d['employee_id']);$req=TrainingRequirement::forCompany($c)->with('topic')->findOrFail($d['training_requirement_id']);$key=hash('sha256',$c.'|'.$employee->id.'|'.$req->id);$linked=DB::table('training_gap_need')->where('company_id',$c)->where('gap_key',$key)->first();if($linked)return back()->with('warning','Ya existe una necesidad activa relacionada con esta brecha.');$existing=TrainingNeed::forCompany($c)->whereNotIn('status',['cancelled','attended'])->where('title','Formación requerida: '.$req->topic->name)->first();$need=$existing?:TrainingNeed::create(['company_id'=>$c,'code'=>'BRECHA-'.now()->format('YmdHis').'-'.$employee->id,'title'=>'Formación requerida: '.$req->topic->name,'description'=>$d['description']??('Brecha detectada para '.$employee->nombre_completo),'origin_type'=>'management','origin_description'=>'Matriz de formación CAP-4','priority'=>$req->priority,'identified_at'=>today(),'target_population_type'=>'specific_employees','target_population_description'=>$employee->nombre_completo,'status'=>'identified','identified_by'=>$employee->id,'created_by'=>$r->user()->id]);DB::table('training_gap_need')->insert(['company_id'=>$c,'gap_key'=>$key,'training_need_id'=>$need->id,'created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return back()->with('success',$existing?'Brecha vinculada a la necesidad activa existente.':'Necesidad creada desde la brecha.');}public function export(Request$r,TrainingGapService$s){$rows=$s->forCompany($r->user()->company_id,$r->only('job','area'))->map(fn($g)=>[$g['employee']->nombre_completo,$g['employee']->cargo,$g['employee']->area_departamento,$g['requirement']->topic->name,$g['status'],$g['priority']])->all();return Excel::download(new TrainingAnalyticsExport($rows,['Trabajador','Cargo','Área','Requisito','Estado','Prioridad'],'Brechas'),'brechas-formacion.xlsx');}}
